<script setup lang="ts">import{Head,useForm}from'@inertiajs/vue3';import PageHeader from '@/Components/Shared/PageHeader.vue';import{Button}from'@/components/ui/button';const props=defineProps<{package:any|null,placements:any[]}>();const f=useForm({name:props.package?.name??'',code:props.package?.code??'',description:props.package?.description??'',duration_days:props.package?.duration_days??30,base_price_cents:props.package?.base_price_cents??0,package_price_cents:props.package?.package_price_cents??0,impression_goal:props.package?.impression_goal??null,click_goal:props.package?.click_goal??null,included_creatives:props.package?.included_creatives??1,billing_terms:props.package?.billing_terms??'Due on receipt',is_active:props.package?.is_active??true,internal_notes:props.package?.internal_notes??'',placement_ids:props.package?.placements?.map((p:any)=>p.id)??[]});const submit=()=>props.package?f.put(`/admin/sponsorship-packages/${props.package.id}`):f.post('/admin/sponsorship-packages');</script><template><Head :title="package?'Edit Sponsorship Package':'Create Sponsorship Package'"/><div class="space-y-6 p-6"><PageHeader :title="package?'Edit Sponsorship Package':'Create Sponsorship Package'" description="Define pricing, duration, goals, and included inventory."/><form @submit.prevent="submit" class="grid gap-5 rounded-xl border p-6 md:grid-cols-2"><label>Name<input v-model="f.name" class="mt-1 w-full rounded-md border p-2"/></label><label>Code<input v-model="f.code" class="mt-1 w-full rounded-md border p-2"/></label><label>Duration days<input v-model.number="f.duration_days" type="number" class="mt-1 w-full rounded-md border p-2"/></label><label>Package price cents<input v-model.number="f.package_price_cents" type="number" class="mt-1 w-full rounded-md border p-2"/></label><label>Base price cents<input v-model.number="f.base_price_cents" type="number" class="mt-1 w-full rounded-md border p-2"/></label><label>Included creatives<input v-model.number="f.included_crea